import {renderPlanComparison} from './plan-comparison.js';
import {intensityPolicy,renderWorkout} from './workout-contract.js';
import {sessionFetch} from './session-client.js';
import {connectAccount,activeSyncOwner,accountChanged,syncMessage,hasSyncConflict,synchronize,resolveSync} from './account-sync.js';
import {adoptSuggestion,setPlanOwner,getActivePlan,exportPlanArchive} from './active-plan.js';
import {validateProfile,validateStoredProfile,validateSuggestion,localToday,addDate} from './training-contract.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let registering=false,editingOwner=null;
let generationJob=null,generationHistory=[],generationOwner=null,jobTimer=null,jobReading=false,loadedJobId=null;
const activeJob=()=>generationOwner===account?.id&&['queued','processing','retrying'].includes(generationJob?.status);
export function needsRegistration(){return !!account&&registering;}
let account=null,authChecked=false,status='',busy=false,result=null,draft=null,displayedResultMarkup='';
const labels=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
const changed=(background=false)=>{const event=new Event('profile-change');event.background=background;event.owner=account?.id||null;window.dispatchEvent(event);};
export function profileEditing(){return !!account&&editingOwner===account.id;}
function key(){return account?'dez-voltas-profile-v1:'+account.id:null;}
function defaults(){return {goal:'distance',target:'',startDate:localToday(),targetDate:addDate(localToday(),90),weeklyKm:'',longestKm:'',weeksConsistent:'',days:[],maxMinutes:45,longMinutes:90,pain:'',consent:false,details:{registrationCompleted:false,eventName:'',terrain:'unspecified',elevationM:null,experience:'unspecified',experienceMonths:null,recentRuns:null,longDay:null,finishMinutes:null,intensity:{recentQuality:'unspecified',qualityWeeks:null,fatigue:null,sleep:null,restriction:'unsure',preference:'balanced'}}};}
// An unfinished form is local to this account and never enters the validated cloud document.
function editKey(){return 'dez-voltas-profile-edit-v1:'+account.id;}
function persistEdit(){if(!account||!draft)return;editingOwner=account.id;try{localStorage.setItem(editKey(),JSON.stringify({version:1,profile:draft}));}catch{status='Sem espaço para guardar o preenchimento neste aparelho. Mantenha esta tela aberta até concluir o cadastro.';const node=document.querySelector('#profile-generation-status');if(node){node.textContent=status;node.hidden=false;}}}
function restoreEdit(){if(!account)return null;try{const text=localStorage.getItem(editKey());if(!text||text.length>12000)return null;const saved=JSON.parse(text);if(saved?.version!==1||!saved.profile||!Array.isArray(saved.profile.days)||saved.profile.days.length>7||saved.profile.days.some(d=>!Number.isInteger(d)||d<0||d>6))return null;
 // Copy only known scalar fields; partial numbers and empty fields need no training validation yet.
 const copy=(template,value)=>Object.fromEntries(Object.entries(template).map(([name,fallback])=>{const v=value?.[name];if(Array.isArray(fallback))return [name,[...saved.profile.days]];if(fallback&&typeof fallback==='object')return [name,copy(fallback,v)];return [name,v===null||['number','boolean'].includes(typeof v)||typeof v==='string'&&v.length<=1000?v:fallback];}));
 const p=copy(defaults(),saved.profile);if(!['distance','time','backyard'].includes(p.goal)||typeof p.startDate!=='string'||typeof p.targetDate!=='string')return null;p.details.registrationCompleted=p.details.registrationCompleted===true;return p;
 }catch{return null;}}
function clearEdit(){if(account)try{localStorage.removeItem(editKey());}catch{}editingOwner=null;}
function load(){const inProgress=profileEditing()?draft:null;editingOwner=null;result=null;draft=null;try{const saved=JSON.parse(localStorage.getItem(key())||'null')||getActivePlan();if(saved){draft=saved.profile;const p=validateStoredProfile(saved.profile,saved.profile.startDate);if(saved.plan)result={...saved,profile:p,plan:validateSuggestion(saved.plan,p)};}const savedDraft=JSON.parse(localStorage.getItem('dez-voltas-draft-v1:'+account.id)||'null');if(savedDraft)draft=validateStoredProfile(savedDraft,savedDraft.startDate);}catch{status='Não foi possível restaurar a sugestão salva. Gere outra ou importe um backup válido.';}const edit=inProgress||restoreEdit();if(edit){draft=edit;editingOwner=account.id;}registering=!!account&&(!draft||draft.details?.registrationCompleted===false);}
async function api(path,body,extraHeaders={}){let r;const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),70000);try{r=await sessionFetch('/api/'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',signal:controller.signal,headers:{'x-dv-training-format':'2',...extraHeaders,...(body===undefined?{}:{'content-type':'application/json'}),...(account&&!path.startsWith('auth/')?{'x-account-id':account.id}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});}catch(error){throw new Error(error.name==='AbortError'?'A solicitação demorou mais de um minuto. Tente novamente. Seu plano anterior foi preservado.':'Sem conexão. Tente novamente online. As cópias salvas não foram removidas.');}finally{clearTimeout(timeout);}if(!r.headers.get('content-type')?.includes('application/json'))throw new Error('Esta versão ainda precisa do servidor configurado no Cloudflare.');const data=await r.json();if(!r.ok){if(r.status===401){account=null;result=null;}throw new Error(data.error||'Não foi possível concluir.');}return data;}
function field(name,label,value,type='number',extra='',required=true){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(typeof value==='number'&&!Number.isFinite(value)?'':value)}" ${required?'required':''} ${extra}></label>`;}
export function renderAccountActions(){return account?`<a class="profile-link" href="#perfil" aria-label="Minha conta e meu objetivo" title="${esc(account.email)}">Minha conta${activeJob()?' · Gerando plano':generationOwner===account.id&&generationJob?.status==='completed'?' · Sugestão pronta':''}</a><button type="button" class="account-logout" data-profile="logout" ${busy?'disabled':''}>Sair</button>`:`<a class="profile-link" href="#perfil">${authChecked?'Entrar':'Minha conta'}</a>`;}
export function renderProfile(){const p=draft||defaults();return `<div class="page-heading"><div><span class="eyebrow">UM PLANO PARA O SEU OBJETIVO</span><h1>${registering?'Vamos preparar seu <em>começo.</em>':'Seu próximo <em>desafio.</em>'}</h1></div>${registering?'':'<a class="secondary" href="#plano">Ver plano atual</a>'}</div>
<section class="panel profile-account"><h2>Sua conta</h2>${account?`<p>Conectado como <strong>${esc(account.email)}</strong></p><button class="secondary" data-profile="logout" ${busy?'disabled':''}>Sair da conta</button><p class="field-help">Conta confirmada. Perfil, planos e diário têm uma cópia neste aparelho e são sincronizados com sua conta.</p>`:`<p>Entre com sua conta Google para acompanhar seu objetivo.</p><button type="button" class="primary google-login" data-profile="google" ${busy?'disabled':''}>Entrar com Google</button><details class="profile-email"><summary>Entrar com link por e-mail</summary><form id="profile-login" class="profile-login">${field('email','Seu e-mail','','email','autocomplete="email" maxlength="254"')}<button class="primary" ${busy?'disabled':''}>${busy?'Aguarde…':'Receber link de acesso'}</button></form><p class="field-help">Abra o link no mesmo navegador em que pediu. No iPhone, o Safari e o app instalado podem ter sessões separadas. ${authChecked?'':'Conferindo acesso…'}</p></details>`}<div class="notice"><p id="account-sync-message" role="status">${esc(syncMessage())}</p><button type="button" class="secondary" data-profile="sync">Sincronizar agora</button><button type="button" class="secondary" data-profile="recovery">Baixar cópia de recuperação</button><span id="account-sync-conflict" ${hasSyncConflict()?'':'hidden'}><p>A escolha abaixo vale apenas para os registros em conflito. Alterações em treinos diferentes são combinadas automaticamente. Uma cópia de recuperação fica guardada neste aparelho.</p><button type="button" class="secondary" data-profile="cloud">Usar valores da nuvem nos conflitos</button><button type="button" class="secondary" data-profile="local">Usar valores deste aparelho nos conflitos</button></span></div><p id="profile-status" class="notice" role="status" aria-live="polite" ${status&&!account?'':'hidden'}>${esc(status)}</p></section>
${account?`<div id="profile-job-region">${renderGeneration()}</div><section class="panel profile-form-panel"><span class="eyebrow muted">PONTO DE PARTIDA</span><h2>${registering?'Complete seu cadastro de corredor.':'Seu objetivo e sua rotina.'}</h2><p class="muted">A base das últimas quatro semanas orienta a sugestão. Um volume alto no passado não substitui a adaptação atual.</p><p class="field-help">Seu preenchimento é guardado neste aparelho para continuar depois, mesmo antes de concluir o cadastro.</p><form id="profile-goal" data-owner="${esc(account.id)}"><fieldset class="onboarding-section"><legend><span>1</span> Seu objetivo</legend><p>Defina o que deseja alcançar. O plano vai avaliar a meta a partir da sua base atual.</p><div class="profile-grid">${selectField('goal','O que você quer preparar?',[['distance','Completar uma distância'],['time','Correr por um período de tempo'],['backyard','Completar voltas em uma backyard']],p.goal)}${field('target',p.goal==='backyard'?'Quantas voltas de 6,7056 km?':p.goal==='time'?'Por quantos minutos quer correr?':'Qual distância quer completar (km)?',p.target,'number',`min="1" max="${p.goal==='time'?1440:p.goal==='backyard'?48:200}" step="${p.goal==='backyard'?1:0.1}"`)}${field('startDate','Quando quer começar?',p.startDate,'date')}${field('targetDate','Data da prova ou do objetivo',p.targetDate,'date')}${field('eventName','Nome da prova (opcional)',p.details?.eventName||'','text','maxlength="120" autocomplete="off"',false)}${selectField('terrain','Terreno da prova ou objetivo',[['unspecified','Ainda não sei'],['road','Asfalto / estrada'],['trail','Trilha'],['mixed','Misto'],['treadmill','Esteira']],p.details?.terrain||'unspecified')}${field('elevationM','Subida acumulada na prova (m, opcional)',p.details?.elevationM,'number','min="0" max="20000" step="1"',false)}${p.goal==='distance'?field('finishMinutes','Tempo desejado para concluir (min, opcional)',p.details?.finishMinutes,'number','min="5" max="3000" step="0.1"',false):''}</div><p class="field-help">O tempo desejado é uma referência para avaliar a viabilidade. Em backyard, cada volta parte a cada hora. Se não souber terreno ou desnível, deixe em aberto.</p></fieldset>
<fieldset class="onboarding-section"><legend><span>2</span> Seu ponto de partida</legend><p>Considere as últimas quatro semanas, incluindo semanas sem correr. Se está começando, informe zero.</p><div class="profile-grid">${selectField('experience','Como você se reconhece hoje?',[['unspecified','Prefiro não informar'],['beginner','Estou começando a correr'],['returning','Estou voltando depois de uma pausa'],['regular','Corro com regularidade'],['experienced','Tenho experiência em provas longas']],p.details?.experience||'unspecified')}${field('experienceMonths','Tempo total de experiência (meses, opcional)',p.details?.experienceMonths,'number','min="0" max="600" step="1"',false)}${field('weeklyKm','Média semanal nas últimas 4 semanas (km)',p.weeklyKm,'number','min="0" max="200" step="0.1"')}${field('longestKm','Maior treino nas últimas 4 semanas (km)',p.longestKm,'number','min="0" max="150" step="0.1"')}${field('recentRuns','Dias de corrida por semana recentemente (opcional)',p.details?.recentRuns,'number','min="0" max="7" step="1"',false)}${field('weeksConsistent','Semanas seguidas treinando atualmente',p.weeksConsistent,'number','min="0" max="520" step="1"')}</div><h3>Experiência com intensidade e recuperação atual</h3><p class="field-help">Estas respostas ajudam a escolher os treinos; não são uma avaliação clínica nem uma liberação para esforço. Preferir mais intensidade não substitui base recente.</p><div class="profile-grid">${selectField('recentQuality','Treinos de ritmo, tiros ou fartlek nas últimas 4 semanas',[['unspecified','Ainda não informei'],['none','Não tenho feito'],['occasional','Fiz ocasionalmente'],['weekly','Tenho feito toda semana']],p.details?.intensity?.recentQuality||'unspecified')}${field('qualityWeeks','Há quantas semanas faz qualidade com regularidade? (opcional)',p.details?.intensity?.qualityWeeks,'number','min="0" max="104" step="1"',false)}${selectField('intensityFatigue','Fadiga atual',[['','Não informado'],['1','1 · muito baixa'],['2','2 · baixa'],['3','3 · moderada'],['4','4 · alta'],['5','5 · muito alta']],p.details?.intensity?.fatigue==null?'':String(p.details.intensity.fatigue))}${selectField('intensitySleep','Qualidade do sono recentemente',[['','Não informado'],['1','1 · muito ruim'],['2','2 · ruim'],['3','3 · regular'],['4','4 · boa'],['5','5 · muito boa']],p.details?.intensity?.sleep==null?'':String(p.details.intensity.sleep))}${selectField('intensityRestriction','Existe restrição profissional para esforço intenso?',[['unsure','Não sei / preciso avaliar'],['none','Não tenho restrição conhecida'],['yes','Sim, tenho restrição']],p.details?.intensity?.restriction||'unsure')}${selectField('intensityPreference','Como prefere a preparação?',[['balanced','Equilibrada, com qualidade quando houver base'],['conservative','Priorizar base e esforço confortável']],p.details?.intensity?.preference||'balanced')}</div><p class="field-help">Para calcular a média: some os quilômetros das quatro semanas e divida por quatro. Seu histórico antigo ajuda a contextualizar, mas não substitui a base recente.</p></fieldset>
<fieldset class="onboarding-section"><legend><span>3</span> O treino na sua rotina</legend><p>Escolha dias e tempos que consegue manter. Disponibilidade é um limite; nem todos os dias precisam ter corrida.</p><fieldset class="profile-days"><legend>Dias disponíveis para correr (2 a 6)</legend>${labels.map((d,i)=>`<label><input type="checkbox" name="days" value="${i}" ${p.days?.includes(i)?'checked':''}> ${d}</label>`).join('')}</fieldset><div class="profile-grid">${field('maxMinutes','Tempo por treino comum (min)',p.maxMinutes,'number','min="20" max="360"')}${field('longMinutes','Tempo disponível para o longo (min)',p.longMinutes,'number','min="30" max="600"')}${selectField('longDay','Dia preferido para o longo',[['','Sem preferência'],...(p.days||[]).map(d=>[String(d),labels[d]])],p.details?.longDay==null?'':String(p.details.longDay))}${selectField('pain','Dor ou retorno de lesão',[['','Selecione sua situação'],['none','Sem dor ou incômodo'],['current','Estou com dor atualmente'],['return','Estou retornando de lesão']],p.pain)}</div><p class="field-help">Com dor atual ou retorno de lesão, salve seu perfil e revise a preparação com um profissional antes de gerar cargas.</p></fieldset>
<fieldset class="onboarding-section"><legend><span>4</span> Confira seu cadastro</legend><div class="onboarding-review">${reviewProfile(p)}</div><p class="field-help">Seu perfil e diário ficam vinculados à sua conta. Salvar o perfil não faz uma chamada ao Gemini.</p><button type="button" class="secondary" data-profile="save-profile" ${busy||!account?'disabled':''}>${registering?'Concluir cadastro':'Salvar meu perfil'}</button></fieldset>${registering?'<p class="notice">Depois de concluir o cadastro, você poderá revisar os dados e autorizar a geração do plano.</p>':`<label class="profile-consent"><input type="checkbox" name="consent" ${p.consent?'checked':''}><span>Autorizo enviar os dados deste formulário, incluindo objetivo, histórico recente, disponibilidade, sono, fadiga, restrição informada e situação de dores ao Google Gemini para gerar a sugestão. Meu e-mail não será enviado ao Gemini. <a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noopener noreferrer">Termos do serviço</a>.</span></label><div class="notice">Você receberá as fases até o objetivo e os primeiros 28 dias detalhados, ou menos se a preparação for menor. A IA pode errar: revise a proposta, ajuste pela recuperação e procure orientação profissional quando necessário.</div><button type="submit" class="primary" ${busy||!account||activeJob()?'disabled':''}>${activeJob()?'Geração em andamento':busy?'Enviando solicitação…':'Gerar sugestão com Gemini'}</button>`}<p id="profile-generation-status" class="notice profile-generation-feedback" role="status" aria-live="polite" ${status&&account?'':'hidden'}>${esc(status)}</p>${!account?'<p class="field-help">Entre na sua conta para gerar. O formulário pode ser preenchido antes.</p>':''}</form></section>${renderResultRegion()}`:'<section class="panel"><h2>Seu cadastro começa com sua conta.</h2><p>Entre com Google ou com seu e-mail. No primeiro acesso, vamos conhecer seu objetivo, sua experiência recente e os dias disponíveis para correr.</p></section>'}`;}
function renderResultRegion(){displayedResultMarkup=!registering&&result?renderResult(result):'';return `<div id="profile-result-region">${displayedResultMarkup}</div>`;}
function renderResult(r){return `<section id="profile-result" class="panel profile-result" tabindex="-1"><span class="eyebrow muted">SUGESTÃO DO GEMINI · REVISE ANTES DE TREINAR</span><h2>${r.profile.review?'Seu próximo bloco, revisado.':'Uma preparação para você.'}</h2>${r.profile.review?`<div class="notice"><strong>Semana ${esc(r.profile.review.weekStart)} a ${esc(r.profile.review.weekEnd)}</strong><p>${esc(r.profile.review.reason)}</p><p>Realizado: ${esc(r.profile.review.observedKm)} km · ${esc(r.profile.review.observedMinutes)} min. A proposta altera os treinos futuros somente se você escolher usá-la; o histórico permanece salvo.</p></div>`:''}${renderPlanComparison(r,{owner:account?.id,plans:exportPlanArchive().plans,activePlan:getActivePlan()})}<p>${esc(r.plan.summary)}</p><div class="notice"><strong>Escolha da intensidade</strong><p>${esc(intensityPolicy(r.profile).reason)}</p><p>O esforço global da sessão é estimado; os trechos fortes têm RPE próprio nas etapas.</p></div><div class="notice"><strong>Avaliação da meta</strong><p>${esc(r.plan.feasibility)}</p></div>${r.plan.warnings.length?`<ul>${r.plan.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<h3>As fases até o objetivo</h3><div class="profile-phases">${r.plan.phases.map(p=>`<article><span class="eyebrow muted">${esc(p.start)} → ${esc(p.end)}</span><h3>${esc(p.title)}</h3><p>${esc(p.focus)}</p></article>`).join('')}</div><h3>Primeiras semanas detalhadas</h3>${r.plan.weeks.map((w,i)=>`<details class="profile-week" ${i===0?'open':''}><summary>Semana ${i+1} · ${esc(w.start)} · ${w.totalKm.toLocaleString('pt-BR')} km</summary><p>${esc(w.focus)}</p>${w.sessions.map(s=>`<article class="profile-session"><strong>${esc(s.date)} · ${esc(s.title)}</strong><p>${s.km.toLocaleString('pt-BR')} km · ${s.minutes} min · RPE ${s.rpe}/10${s.long?' · Longo':''}</p><p>${esc(s.instructions)}</p>${renderWorkout(s.workout)}</article>`).join('')||'<p>Recuperação e descanso.</p>'}</details>`).join('')}<p class="field-help">Reavalie por volta de ${esc(r.plan.reviewDate)} com os treinos efetivamente realizados. Modelo: ${esc(r.model)}. Gerado em ${esc(new Date(r.generatedAt).toLocaleString('pt-BR'))}.</p><div class="profile-buttons"><button class="primary" data-profile="adopt">Usar este plano</button><button class="secondary" data-profile="save">Salvar sugestão na conta</button><button class="secondary" data-profile="export">Baixar sugestão (JSON)</button></div><p class="field-help">“Usar este plano” atualiza Plano, Hoje e as sessões para registro. “Salvar sugestão” guarda apenas esta proposta. Seu histórico anterior é preservado. Novas sugestões só entram no calendário quando você escolher usá-las.</p></section>`;}
function selectField(name,label,options,value){return `<label class="field">${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function reviewProfile(p){const ready=typeof p.target==='number'&&Number.isFinite(p.target)&&p.target>0;const goal=ready?`${p.target} ${p.goal==='backyard'?'voltas':p.goal==='time'?'minutos':'km'}`:'Informe sua meta';const days=(p.days||[]).map(d=>labels[d]).join(', ')||'Escolha seus dias';const duration=(Date.parse(p.targetDate)-Date.parse(p.startDate))/86400000;return `<p><strong>${esc(goal)}</strong> · ${Number.isFinite(duration)&&duration>=0?Math.floor(duration)+' dias de preparação':'Confira as datas'}</p><p>${esc(days)} · até ${esc(p.maxMinutes)} min por treino comum · até ${esc(p.longMinutes)} min no longo</p><p>A base recente orienta as primeiras semanas. O plano detalha até 28 dias e define fases a revisar até seu objetivo.</p><p class="field-help">${esc(intensityPolicy(p).reason)}</p>`;}
function readForm(){const form=document.querySelector('#profile-goal');if(!form)return draft;const f=new FormData(form);const numeric=name=>{const value=f.get(name);return value==null||String(value).trim()===''?NaN:Number(value);};const optional=name=>{const value=f.get(name);return value==null||String(value).trim()===''?null:Number(value);};return {goal:f.get('goal'),target:numeric('target'),startDate:f.get('startDate'),targetDate:f.get('targetDate'),weeklyKm:numeric('weeklyKm'),longestKm:numeric('longestKm'),weeksConsistent:numeric('weeksConsistent'),maxMinutes:numeric('maxMinutes'),longMinutes:numeric('longMinutes'),pain:f.get('pain'),days:f.getAll('days').map(Number),consent:f.get('consent')==='on',details:{registrationCompleted:!registering,eventName:f.get('eventName')||'',terrain:f.get('terrain')||'unspecified',elevationM:optional('elevationM'),experience:f.get('experience')||'unspecified',experienceMonths:optional('experienceMonths'),recentRuns:optional('recentRuns'),longDay:optional('longDay'),finishMinutes:f.get('goal')==='distance'?optional('finishMinutes'):null,intensity:{recentQuality:f.get('recentQuality')||'unspecified',qualityWeeks:optional('qualityWeeks'),fatigue:optional('intensityFatigue'),sleep:optional('intensitySleep'),restriction:f.get('intensityRestriction')||'unsure',preference:f.get('intensityPreference')||'balanced'}}};}
function rememberDraft(){const form=document.querySelector('#profile-goal');if(form?.dataset?.owner&&form.dataset.owner!==account?.id)return;draft=readForm();if(document.querySelector('#profile-goal'))persistEdit();if(account&&draft){try{const p=validateStoredProfile(draft,draft.startDate);localStorage.setItem('dez-voltas-draft-v1:'+account.id,JSON.stringify(p));accountChanged();}catch{ /* Incomplete forms remain in the separate local edit, not the cloud profile. */ }}}
function revealFeedback(resultReady=false){requestAnimationFrame(()=>{const node=document.querySelector(resultReady?'#profile-result':account?'#profile-generation-status':'#profile-status');node?.scrollIntoView?.({block:'nearest',behavior:'smooth'});if(resultReady)node?.focus?.({preventScroll:true});});}
document.addEventListener('invalid',e=>{if(!e.target.closest('#profile-goal'))return;status='Confira os campos obrigatórios e marque a autorização de envio ao Gemini.';const node=document.querySelector('#profile-generation-status');if(node){node.textContent=status;node.hidden=false;}},true);
document.addEventListener('input',e=>{if(e.target.closest('#profile-goal')&&!['goal','days'].includes(e.target.name))rememberDraft();});
document.addEventListener('change',e=>{if(!e.target.closest('#profile-goal'))return;draft=readForm();if(e.target.name==='goal'){draft.target='';draft.details.finishMinutes=null;persistEdit();changed();}else if(e.target.name==='days'){if(!draft.days.includes(draft.details.longDay))draft.details.longDay=null;persistEdit();changed();}else{rememberDraft();const summary=document.querySelector('.onboarding-review');if(summary)summary.innerHTML=reviewProfile(draft);}});
document.addEventListener('submit',async e=>{
 if(!['profile-login','profile-goal'].includes(e.target.id))return;e.preventDefault();if(busy)return;
 let generated=false;const login=e.target.id==='profile-login',email=login?new FormData(e.target).get('email'):null;rememberDraft();let profile;
 if(!login&&registering){status='Conclua seu cadastro antes de gerar o plano.';changed();revealFeedback();return;}
 if(!login){try{profile=validateProfile(draft);if(profile.pain!=='none')throw new Error('Com dor atual ou retorno de lesão, revise a preparação com um profissional antes de gerar cargas.');}catch(error){status=error.message;changed();revealFeedback();return;}}
 if(!login)clearEdit();
 const submitOwner=account?.id;busy=true;status=login?'Solicitando seu link de acesso…':'Salvando sua solicitação na fila…';changed();if(!login)revealFeedback();
 try{if(login){const data=await api('auth/link',{email});status=data.message;}else{if(activeJob())throw new Error('Já existe uma geração em andamento para sua conta.');
 const pendingKey='dez-voltas-generation-request-v1:'+submitOwner;let pending;try{pending=JSON.parse(localStorage.getItem(pendingKey)||'null');}catch{}
 if(!pending||pending.profile!==JSON.stringify(profile))pending={id:crypto.randomUUID(),profile:JSON.stringify(profile)};
 localStorage.setItem(pendingKey,JSON.stringify(pending));
 const data=await api('training/suggest',profile,{'idempotency-key':pending.id});
 if(account?.id!==submitOwner)return;
 generationOwner=submitOwner;generationJob=data.job;localStorage.setItem(pendingKey,'null');
 status='Solicitação salva. Pode sair desta tela ou fechar o app: a geração continua no servidor.';
 scheduleJobs();}}catch(error){status=error.message;}finally{busy=false;changed();if(!login)revealFeedback(generated);}
});
document.addEventListener('click',async e=>{const action=e.target.closest('[data-profile]')?.dataset.profile;if(!action||busy)return;
 if(action==='jobs')await refreshJobs(true);
 if(action==='job-result'){const id=e.target.closest('[data-job-id]')?.dataset.jobId;if(id)await refreshJobs(true,id);}
 if(action==='save-profile'&&account){rememberDraft();try{const wasRegistering=registering;const profile=validateStoredProfile({...draft,details:{...draft.details,registrationCompleted:true}},localToday());localStorage.setItem('dez-voltas-draft-v1:'+account.id,JSON.stringify(profile));draft=profile;registering=false;clearEdit();accountChanged();location.hash='#perfil';status=wasRegistering?'Cadastro concluído. Confira os dados e autorize a geração do seu primeiro plano.':'Perfil salvo. Confira acima a sincronização com sua conta.';}catch(error){status=error.message;}changed();revealFeedback();}
 if(action==='google'){rememberDraft();busy=true;status='Abrindo o acesso com Google…';changed();try{const data=await api('auth/google',{});location.assign(data.url);}catch(error){status=error.message;busy=false;changed();}}
 if(action==='adopt'&&result&&account){try{const current=JSON.parse(localStorage.getItem('dez-voltas-draft-v1:'+account.id)||'null');const currentIntensity=current?.details?.intensity;if((current?.pain&&current.pain!=='none'||currentIntensity&&(currentIntensity.restriction!=='none'||currentIntensity.preference==='conservative'||currentIntensity.fatigue>=4||currentIntensity.sleep!=null&&currentIntensity.sleep<=2))&&result.plan.weeks.some(w=>w.sessions.some(s=>['fartlek','tempo','interval'].includes(s.workout?.type))))throw new Error('Seus dados atuais pedem base ou revisão antes de adotar treinos de qualidade. Atualize o cadastro e gere uma proposta compatível.');if(result.profile.review){if(getActivePlan()?.id!==result.profile.review.sourcePlanId)throw new Error('O plano em uso mudou desde esta revisão. Faça um novo fechamento antes de aplicar alterações.');const latest=JSON.parse(localStorage.getItem('dez-voltas-draft-v1:'+account.id)||'null');if(latest?.pain&&latest.pain!=='none')throw new Error('Atualize a recuperação com um profissional antes de adotar novas cargas.');}adoptSuggestion(account.id,result);status='Plano adotado. A sincronização enviará a alteração à sua conta. Abra a seção Plano para ver seus treinos.';window.dispatchEvent(new Event('active-plan-change'));location.hash='#plano';}catch(error){status=error.message;}changed();}
 if(action==='recovery'&&account){const backup=localStorage.getItem('dez-voltas-cloud-v2:'+account.id+':recovery');if(!backup){status='Nenhuma cópia de recuperação foi necessária neste aparelho.';changed();}else{const saved=JSON.parse(backup);const portable={...saved.state,app:'dez-voltas',generatedPlans:saved.archive,exportedAt:new Date().toISOString(),accountProfile:saved.profile,accountDraft:saved.draft};const url=URL.createObjectURL(new Blob([JSON.stringify(portable,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='dez-voltas-recuperacao.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}}
 if(action==='sync')await synchronize();
 if(action==='cloud'||action==='local'){if(confirm(action==='local'?'Usar os valores deste aparelho nos registros em conflito? Os demais registros serão mantidos.':'Usar os valores da nuvem nos registros em conflito? Sua cópia local ficará guardada para recuperação.'))await resolveSync(action==='local');}
 if(action==='save'&&result&&account){try{localStorage.setItem(key(),JSON.stringify(result));accountChanged();status='Sugestão salva na cópia local e aguardando sincronização com sua conta.';}catch{status='Não foi possível salvar. Baixe a sugestão para guardar uma cópia.';}changed();}
 if(action==='export'&&result){const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='dez-voltas-sugestao-'+result.profile.startDate+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 if(action==='logout'){rememberDraft();busy=true;try{await api('auth/logout',{});editingOwner=null;account=null;resetJobs();registering=false;setPlanOwner(null);await connectAccount(null);location.hash='#perfil';window.dispatchEvent(new Event('active-plan-change'));result=null;draft=null;status='Você saiu da conta. As cópias salvas continuam neste aparelho.';}catch(error){status=error.message;}finally{busy=false;changed();}}
});
export async function initProfile(){try{const url=new URL(location.href),hash=new URLSearchParams(url.hash.slice(1)),code=url.searchParams.get('code'),error=url.searchParams.get('error_description')||hash.get('error_description'),errorCode=url.searchParams.get('error')||hash.get('error');if(code||url.searchParams.has('auth')||error||errorCode){history.replaceState(null,'','/#perfil');if(error||errorCode)throw new Error(errorCode==='access_denied'?'A entrada foi cancelada. Tente novamente ou use o link por e-mail.':'Não foi possível concluir o acesso. Tente entrar novamente.');if(!code)throw new Error('Link incompleto. Solicite outro e use o mesmo navegador.');const data=await api('auth/callback',{code});account=data.user;setPlanOwner(account.id);load();await connectAccount(account.id);load();status='Acesso confirmado. Preencha seu objetivo para gerar uma sugestão.';}else{const data=await api('auth/me');account=data.user;setPlanOwner(account?.id||null);if(account)load();await connectAccount(account?.id||null);if(account)load();}}catch(error){status=error.message;}finally{authChecked=true;if(account)void refreshJobs();if(needsRegistration())location.hash='#perfil';changed();window.dispatchEvent(new Event('active-plan-change'));}}

window.addEventListener('account-data-loaded',()=>{if(account){load();if(profileEditing())updateGenerationUI();changed(true);}});
window.addEventListener('sync-status',()=>{const node=document.querySelector('#account-sync-message');if(node)node.textContent=syncMessage();const conflict=document.querySelector('#account-sync-conflict');if(conflict)conflict.hidden=!hasSyncConflict();});

async function clearAccountSession(message){editingOwner=null;account=null;resetJobs();registering=false;result=null;draft=null;setPlanOwner(null);await connectAccount(null);status=message;location.hash='#perfil';changed();}
window.addEventListener('session-ended',()=>{void clearAccountSession('Você saiu da conta em outra aba.');});
window.addEventListener('session-expired',()=>{void clearAccountSession('Sua sessão terminou. Entre novamente; os dados locais foram preservados.');});
window.addEventListener('session-account-change',async event=>{account=event.detail;resetJobs();setPlanOwner(account.id);await connectAccount(account.id);load();location.hash='#perfil';status='A conta ativa foi alterada em outra aba.';void refreshJobs();changed();});

window.addEventListener('session-restored',async event=>{if(account||!authChecked)return;account=event.detail;resetJobs();setPlanOwner(account.id);if(activeSyncOwner()!==account.id)await connectAccount(account.id);load();status='Acesso restabelecido automaticamente. Seus dados continuam salvos.';void refreshJobs();changed();});

function resetJobs(){clearTimeout(jobTimer);jobTimer=null;generationJob=null;generationHistory=[];generationOwner=null;loadedJobId=null;}
function scheduleJobs(){clearTimeout(jobTimer);if(account&&document.visibilityState==='visible'){jobTimer=setTimeout(()=>void refreshJobs(),activeJob()?6000:60000);}}
function renderGeneration(){
 if(generationOwner!==account?.id||!generationJob)return '';
 const j=generationJob,labels={queued:'Na fila',processing:'Preparando sua sugestão',retrying:'Nova tentativa programada',completed:'Sugestão pronta para revisão',failed:'Não foi possível gerar'};
 return `<section class="panel generation-panel" aria-label="Acompanhamento da geração"><span class="eyebrow muted">GERAÇÃO DO PLANO</span><h2 id="generation-job-status" role="status" aria-live="polite">${esc(labels[j.status]||'Conferindo geração')}</h2><p>${activeJob()?'Pode sair desta tela ou fechar o app. Sua solicitação está salva e o processamento continua no servidor. A fila é verificada a cada minuto.':j.status==='completed'?'O resultado está salvo na sua conta. Revise abaixo e escolha se deseja usar este plano.':'Seu plano anterior foi preservado. Confira o cadastro antes de fazer uma nova solicitação.'}</p>${j.error?`<p class="notice">${esc(j.error)}</p>`:''}${j.status==='retrying'?`<p>Próxima tentativa a partir de ${esc(new Date(j.next_attempt_at).toLocaleString('pt-BR'))}.</p>`:''}<p class="field-help">Tentativas: ${Number(j.attempts)||0} de 2. Até 5 solicitações por conta ao dia, renovadas à meia-noite UTC. Uma solicitação em andamento por conta.</p><button type="button" class="secondary" data-profile="jobs">Atualizar andamento</button>${generationHistory.filter(x=>x.status==='completed'&&x.id!==j.id).length?`<details><summary>Sugestões anteriores</summary>${generationHistory.filter(x=>x.status==='completed'&&x.id!==j.id).map(x=>`<p><button type="button" class="secondary" data-profile="job-result" data-job-id="${esc(x.id)}">Abrir sugestão de ${esc(new Date(x.created_at).toLocaleString('pt-BR'))}</button></p>`).join('')}</details>`:''}</section>`;
}
function updateGenerationUI(){
 const form=document.querySelector('#profile-goal');if(!account||form?.dataset?.owner!==account.id)return;
 const tracker=document.querySelector('#profile-job-region');if(tracker)tracker.innerHTML=renderGeneration();
 const preview=document.querySelector('#profile-result-region'),markup=!registering&&result?renderResult(result):'';if(preview&&markup!==displayedResultMarkup){preview.innerHTML=markup;displayedResultMarkup=markup;}
 const feedback=document.querySelector('#profile-generation-status');if(feedback){feedback.textContent=status;feedback.hidden=!status;}
}
async function refreshJobs(manual=false,id=null){
 const owner=account?.id;if(!owner||jobReading)return;jobReading=true;
 try{
  let data=await api('training/jobs'+(id?'?id='+encodeURIComponent(id):''));
  if(account?.id!==owner)return;
  if(data.job?.status==='completed'&&!data.job.result&&(id||loadedJobId!==data.job.id)){data=await api('training/jobs?id='+encodeURIComponent(data.job.id));if(account?.id!==owner)return;}
  const previous=generationOwner===owner?generationJob:null;
  generationOwner=owner;if(!id)generationJob=data.job;generationHistory=data.history||[];
  if(data.job?.status==='completed'&&data.job.result){
   const raw=data.job.result,p=validateStoredProfile(raw.profile,raw.profile.startDate),plan=validateSuggestion(raw.plan,p);
   const saved={...raw,profile:p,plan};loadedJobId=data.job.id;
   // Loading a cloud result never adopts it or replaces a newer saved suggestion silently.
   if(id||!result||Date.parse(saved.generatedAt)>Date.parse(result.generatedAt)){
    result=saved;localStorage.setItem(key(),JSON.stringify(result));accountChanged();
   }
   if(manual||previous?.id===data.job.id&&previous.status!=='completed'){status='Sugestão pronta e salva na conta. Revise antes de usar.';if(manual||!profileEditing())revealFeedback(true);}
  }
  if(data.job?.status==='failed')status=data.job.error||'Não foi possível gerar a sugestão. Confira o acompanhamento da geração.';
  else if(manual&&data.job?.status!=='completed')status=data.job?'Andamento atualizado.':'Você ainda não tem uma geração solicitada.';
  // Update job/result regions separately when the rest of the form is being edited.
  if(!manual&&profileEditing())updateGenerationUI();
  // Background updates must not replace an editor or dismiss a mobile keyboard.
  if(manual||previous?.id!==data.job?.id||previous?.status!==data.job?.status||previous?.error!==data.job?.error)changed(!manual);
 }catch(error){if(account?.id===owner&&(manual||activeJob())){status=error.message;if(manual)changed();else updateGenerationUI();}}
 finally{jobReading=false;scheduleJobs();}
}
window.addEventListener('focus',()=>{void refreshJobs();});
window.addEventListener('online',()=>{void refreshJobs();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')void refreshJobs();else clearTimeout(jobTimer);});
